const screens=[...pages,...extraScreens];
const defaults={};pages.forEach(p=>{if(!p.binding)p.rows.forEach(r=>defaults[r.id]=r.value)});
let state={settings:{...defaults},bindings:{},callsign:'Hunter',items:['rifle','shotgun','grapple','pack','patch'],selected:0,equipped:0,lesson:5,reportType:'Bug',reportText:'',download:68,mapZoom:1,mapPan:{x:0,y:0},marker:{x:340,y:460}};
let storageAvailable=true;try{const saved=JSON.parse(localStorage.getItem('orbit-ui-prototype-v1')||'null');if(saved){state.settings={...defaults,...saved.settings};state.bindings=saved.bindings||{};state.callsign=saved.callsign||'Hunter'}}catch{storageAvailable=false}
function persist(){try{localStorage.setItem('orbit-ui-prototype-v1',JSON.stringify({settings:state.settings,bindings:state.bindings,callsign:state.callsign}));storageAvailable=true}catch{storageAvailable=false}applyAccessibility();}
function applyAccessibility(){document.body.classList.toggle('reduce-motion',!!state.settings.reducedMotion);document.body.classList.toggle('high-contrast',!!state.settings.highContrast);}
let current='main',returnTo='main',lastSettings='mouse',helpIndex=0,toastTimer=null,modalOrigin=null,capture=null,gamepadTimer=null;
const app=$('#app'),dropdown=$('#dropdown'),modal=$('#modal');
function notify(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),2500)}
function nav(id){if(!screens.some(s=>s.id===id))id='main';if(modal.open)modal.close();if(dropdown.matches(':popover-open'))dropdown.hidePopover();capture=null;clearInterval(gamepadTimer);current=id;location.hash=id;render();}
function head(back='main'){return '<div class="screen-head"><img class="logo" src="assets/logos/orbit-royale-primary.svg" alt="Orbit Royale"><div class="line"></div><button class="action" data-nav="'+back+'"><span class="key">Esc</span> Back</button></div>';}
function footer(saved=false){return '<div class="footer">'+(saved?'<button class="hint" data-action="reset"><span class="key">R</span> RESTORE DEFAULTS</button>':'')+'<span class="hint"><span class="key">Enter</span> SELECT</span><span class="hint"><span class="key">←</span><span class="key">→</span> ADJUST</span>'+(saved?'<span class="saved">'+(storageAvailable?'SAVED ON THIS DEVICE':'CHANGES KEPT FOR THIS SESSION')+'</span>':'')+'</div>';}
function menuAction(label,id,index=0,active=false,action='nav'){return '<button class="menu-action '+(active?'active':'')+'" data-'+action+'="'+id+'">'+(index?'<span class="menu-index">0'+index+'</span>':'')+label+'<span class="arrow" aria-hidden="true">→</span></button>';}
function fmt(r){const v=state.settings[r.id];return r.unit==='×'?(v/100).toFixed(2)+'×':v+(r.unit||'');}
function control(r,disabled=false){const d=disabled?' disabled':'',value=state.settings[r.id];if(r.type==='range')return '<button class="adjust" data-adjust="'+r.id+'" data-direction="-1" aria-label="Decrease '+esc(r.label)+'"'+d+'>‹</button><input type="range" id="'+r.id+'" data-range="'+r.id+'" min="'+r.min+'" max="'+r.max+'" step="'+r.step+'" value="'+value+'" style="--fill:'+((value-r.min)/(r.max-r.min)*100)+'%" aria-label="'+esc(r.label)+'"'+d+'><output for="'+r.id+'" class="value">'+fmt(r)+'</output><button class="adjust" data-adjust="'+r.id+'" data-direction="1" aria-label="Increase '+esc(r.label)+'"'+d+'>›</button>';
 if(r.type==='segments')return '<div class="segments">'+r.options.map(o=>'<button class="'+(value===o?'active':'')+'" data-segment="'+r.id+'" data-value="'+esc(o)+'" aria-pressed="'+(value===o)+'"'+d+'>'+esc(o)+'</button>').join('')+'</div>';
 if(r.type==='toggle')return '<button class="choice-trigger toggle '+(value?'on':'')+'" data-toggle="'+r.id+'" aria-label="'+esc(r.label)+'" aria-pressed="'+value+'"'+d+'>'+(value?'On':'Off')+'</button>';
 return '<button class="adjust" data-adjust="'+r.id+'" data-direction="-1" aria-label="Previous '+esc(r.label)+'"'+d+'>‹</button><button class="choice-trigger" data-choice="'+r.id+'" aria-label="'+esc(r.label)+'" aria-haspopup="listbox" aria-expanded="false"'+d+'>'+esc(value)+'<span class="chevron">▾</span></button><button class="adjust" data-adjust="'+r.id+'" data-direction="1" aria-label="Next '+esc(r.label)+'"'+d+'>›</button>';
}
function helpArt(kind){
 if(icons[kind])return icon(kind);
 if(kind==='curve')return svg('<path d="M10 90V10M10 90h80M10 90Q70 82 90 10" stroke-width="2"/><path d="M10 90 90 10" stroke="#c5f277" stroke-dasharray="4 4"/>');
 if(kind==='deadzone')return svg('<circle cx="28" cy="50" r="23"/><circle cx="73" cy="50" r="23"/><circle cx="28" cy="50" r="8" fill="#213047" stroke="#c5f277"/><circle cx="73" cy="50" r="7" fill="#213047" stroke="#c5f277"/>');
 if(kind==='display'||kind==='safearea')return svg('<rect x="7" y="16" width="86" height="66"/><rect x="15" y="24" width="70" height="50" stroke="#c5f277" stroke-dasharray="3 3"/><path d="M47 49h6m-3-3v6"/><path d="M28 65h8m4 0h8m4 0h8m4 0h8"/>');
 if(kind==='motion')return svg('<rect x="5" y="35" width="22" height="22" opacity=".3"/><rect x="12" y="42" width="22" height="22" opacity=".6"/><rect x="19" y="49" width="22" height="22"/><path d="M47 40v40"/><rect x="60" y="49" width="22" height="22" stroke="#c5f277"/>');
 if(kind==='hud')return '<div style="color:var(--cyan);display:flex;gap:16px;align-items:center">'+icon('shield')+'<span class="numeric">75</span></div><div style="color:var(--coral);display:flex;gap:16px;align-items:center;margin:20px 0">'+icon('health')+'<span class="numeric">100</span></div><div style="display:flex;gap:8px;height:45px">'+state.items.map(id=>'<div style="width:50px;border:1px solid var(--rule)">'+itemIcon(id)+'</div>').join('')+'</div>';
 if(kind==='quality')return '<div style="font-size:18px;line-height:2.4;color:var(--muted)">Low — faster performance<br>Medium — balanced<br>High — more detail<br>Ultra — highest cost<br>Custom — manual settings</div>';
 return icon('target');
}
function helpContent(p,i){if(p.binding)return '<h2>'+(p.controller?'Customize bindings':'Rebind controls')+'</h2><p>Select a binding to change it. Capture a new input, clear a binding, or cancel. Conflicts are shown before a change is saved.</p><div class="help-art">'+icon(p.art)+'</div>'+(p.controller?'<p>No controller connected unless detected.</p>':'');const r=p.rows[i]||p.rows[0];return '<h2>'+esc(r.label)+'</h2><p>'+esc(r.help||'Adjust '+r.label.toLowerCase()+' to suit your preference.')+'</p><div class="help-art">'+helpArt(p.art)+'</div>'+(p.category===1?'<p class="controller-status">'+controllerStatus()+'</p>':'');}
function controllerStatus(){return navigator.getGamepads&&[...navigator.getGamepads()].some(Boolean)?'Controller detected':'No controller connected';}
function settingsScreen(id){const p=pages.find(p=>p.id===id)||pages[0];lastSettings=p.id;helpIndex=Math.min(helpIndex,p.rows.length-1);const local=pages.filter(x=>x.category===p.category);let rows='';
 if(p.binding){rows='<div class="binding-head"><span>Action</span><span>'+(p.controller?'Button':'Primary')+'</span><span>'+(p.controller?'':'Secondary')+'</span></div>'+p.rows.map(([name,key],i)=>{const k=p.id+':'+i;const val=state.bindings[k]||[key,'—'];return '<div class="setting-row" data-help="'+i+'"><span class="setting-label">'+name+'</span><button class="bind-button" data-bind="'+k+'" data-column="0" aria-label="Rebind '+name+'">'+esc(val[0])+'</button>'+(p.controller?'<span></span>':'<button class="bind-button" data-bind="'+k+'" data-column="1" aria-label="Secondary binding for '+name+'">'+esc(val[1])+'</button>')+'</div>';}).join('');}
 else rows=(p.disabled?'<p class="planned">PLANNED ONLINE FEATURE</p>':'')+p.rows.map((r,i)=>'<div class="setting-row '+(i===helpIndex?'active':'')+'" data-help="'+i+'"><label class="setting-label" '+(r.type==='range'?'for="'+r.id+'"':'')+'>'+esc(r.label)+'</label><div class="control">'+control(r,p.disabled)+(p.disabled?'<span class="muted" style="font-size:13px">Unavailable</span>':'')+'</div></div>').join('');
 return '<section class="screen settings-screen">'+head(returnTo)+'<h1>Settings</h1><div class="categories">'+categories.map((c,i)=>'<button class="action category '+(i===p.category?'selected':'')+'" data-nav="'+pages.find(x=>x.category===i).id+'">'+icon(catIcons[i])+c+'</button>').join('')+'</div><div class="subtabs" role="tablist" aria-label="'+categories[p.category]+'">'+local.map(x=>'<button role="tab" aria-selected="'+(x.id===id)+'" class="subtab '+(x.id===id?'active':'')+'" data-nav="'+x.id+'">'+x.tab+'</button>').join('')+'</div><div class="settings-body"><div class="frame settings-rows '+(p.binding?'bindings':'')+'">'+rows+'</div><aside class="frame help" id="help-panel">'+helpContent(p,helpIndex)+'</aside></div>'+footer(true)+'</section>';
}
function mapArt(mini=false){const labels=[['CROWN OBSERVATORY',460,110],['ANCHORPORT',180,280],['GLASS BASIN',470,340],['BLOOMWILD',720,285],['RELAY NINE',280,530],['THE SPINE',485,600],['HOLLOW ARRAY',720,545]];let forest='';for(let i=0;i<65;i++){const a=i*2.4,x=470+Math.sin(a)*280,y=350+Math.cos(a)*240;forest+='<circle cx="'+x.toFixed(1)+'" cy="'+y.toFixed(1)+'" r="'+(3+i%7)+'" fill="#344c42" opacity=".7"/>';}
 const body='<defs><pattern id="'+(mini?'mini':'big')+'-grid" width="40" height="40" patternUnits="userSpaceOnUse"><path d="M40 0H0V40" fill="none" stroke="#33445b" stroke-width=".7"/></pattern></defs><rect width="940" height="700" fill="#0d1827"/><rect width="940" height="700" fill="url(#'+(mini?'mini':'big')+'-grid)"/><g id="'+(mini?'mini-map':'map-content')+'" transform="translate('+(!mini?state.mapPan.x:0)+' '+(!mini?state.mapPan.y:0)+') scale('+(!mini?state.mapZoom:1)+')"><path d="M160 120 255 65 340 88 402 35 510 54 585 88 670 70 710 124 805 140 780 200 850 242 821 320 860 382 808 422 820 510 760 555 682 565 600 660 505 633 424 678 380 605 276 620 258 557 170 540 180 450 106 420 145 345 106 272 161 242 120 179Z" fill="#1d303c" stroke="#7191a6" stroke-width="3"/>'+forest+'<path d="M372 242 480 185 586 245 627 350 568 435 450 489 358 390 320 314Z" fill="#254e64" stroke="#508ba5" stroke-width="4"/><path d="M422 275 493 249 548 293 568 350 515 385 442 401 392 342Z" fill="#326e81"/><path d="M179 280 300 235 432 115 605 189 735 284 718 515 482 593 292 540 178 280M300 235 328 495 482 593M605 189 634 465 718 515" fill="none" stroke="#8b9da8" stroke-width="5" opacity=".7"/>'+labels.map(([n,x,y],i)=>'<g><rect x="'+(x-34)+'" y="'+(y-25)+'" width="68" height="42" fill="#60718a"/><path d="M'+(x-48)+' '+(y+27)+'h96m-45-64v82" stroke="#8b9da8"/>'+(mini?'':'<rect x="'+(x-88)+'" y="'+(y+30)+'" width="176" height="28" fill="#0b101b" stroke="#60718a"/><text x="'+x+'" y="'+(y+49)+'" text-anchor="middle" font-family="Oxanium,sans-serif" font-size="13" font-weight="700" fill="#f3f5fa" stroke="none">'+n+'</text>')+'</g>').join('')+'<circle cx="477" cy="350" r="290" fill="none" stroke="white" stroke-width="4"/><circle cx="440" cy="352" r="190" fill="none" stroke="#b4bfd0" stroke-dasharray="8 7" stroke-width="2"/><path d="M560 470 589 485 564 497Z" fill="white"/>'+(!mini&&state.marker?'<g transform="translate('+state.marker.x+' '+state.marker.y+')"><path d="M0 0c-18-28-22-40 0-40s18 12 0 40Z" fill="#c5f277"/><circle cy="-23" r="6" fill="#0b101b"/></g>':'')+'</g>';
 return svg(body,'0 0 940 700','map-art');}
function shipArt(){return svg('<path d="M20 120 90 90l50 10 110-30 230 26 65 25-70 50-245 12-98-34-75 9Z"/><path d="M170 95 160 35l28 5 32 46m85 0 1-62 33 9 22 60M80 107v43m65-45 18 52m60-52 20 67m83-78 13 80m70-66 10 60"/><circle cx="91" cy="122" r="18"/><circle cx="132" cy="129" r="17"/><path d="M245 113h160v44H250ZM448 114h44v27h-44M15 207h540" stroke="#b4bfd0"/><path d="M40 228h170m250 0h80M42 20h150m250 0h80" stroke="#c5f277"/>','0 0 580 260','map-art');}
function hudScreen(){const equipped=state.items[state.equipped],data=itemInfo[equipped];const inset=state.settings.safeInset;return '<section class="hud" style="--hud-scale:'+state.settings.hudScale/100+'"><button class="frame hud-minimap" data-nav="map" aria-label="Open Ringfall map">'+mapArt(true)+'<span class="storm-label">STORM<strong>01:42</strong></span></button><div class="compass">'+['W','NW','N','NE','E'].map((n,i)=>'<span class="'+(n==='N'?'north':'')+'">'+n+'<small>'+[285,330,'',60,90][i]+'</small></span>').join('')+'</div><div class="hud-counters"><div class="hud-counter">'+icon('person')+'<strong>23</strong> LEFT</div><div class="hud-counter">'+icon('target')+'<strong>4</strong> ELIMS</div></div><button class="action hud-menu-button" data-nav="match-menu">Esc Menu</button><div class="crosshair '+(state.settings.crosshair==='Dot'?'dot':state.settings.crosshair==='Circle'?'circle':'')+'" style="scale:'+state.settings.crosshairSize/100+'"></div><div class="hud-vitals">'+meter('shield',75,'cyan')+meter('health',100,'coral')+'</div><div class="hotbar">'+state.items.map((id,i)=>'<button class="quick-slot '+(state.equipped===i?'active':'')+'" data-equip="'+i+'" aria-label="Slot '+(i+1)+' '+(itemInfo[id]?.name||'empty')+'"><span class="number">'+(i+1)+'</span>'+itemIcon(id)+'<span class="quantity">'+(id==='pack'?3:id==='patch'?6:'')+'</span></button>').join('')+'</div><div class="frame hud-ammo"><strong>'+(data?.type==='weapon'?data.count:'—')+'</strong> <small>/ '+(data?.type==='weapon'?data.reserve:'—')+'</small><p>'+esc(data?(equipped==='rifle'?'AR-7 WAYFARER':data.name.toUpperCase()):'EMPTY SLOT')+'</p></div><div class="hud-hints">1–5 Select slot · Tab Inventory · M Map · Esc Menu</div></section>';}
function meter(name,value,color){return '<div class="hud-meter '+color+'">'+icon(name)+'<div class="segments-meter">'+[0,1,2,3].map(i=>'<span class="'+(value<=i*25?'empty':'')+'"></span>').join('')+'</div><strong>'+value+'</strong></div>';}
function countText(id){const d=itemInfo[id];if(!d)return '';if(id==='grapple')return '<span class="lime" style="font-size:22px">READY</span>';return d.count+' <small>/ '+d.reserve+'</small>';}
function inventoryScreen(){const id=state.items[state.selected],d=itemInfo[id];return '<section class="screen inventory-screen"><div class="inventory-head"><h1>Inventory</h1><div class="vitals-inline"><div class="cyan"><strong>75</strong>'+icon('shield')+'<span class="eyebrow cyan">SHIELDS</span></div><div class="coral"><strong>100</strong>'+icon('health')+'<span class="eyebrow coral">HEALTH</span></div></div></div><div class="inventory-body"><div class="inventory-list">'+state.items.map((id,i)=>{const data=itemInfo[id];return '<button class="inventory-item '+(i===state.selected?'active':'')+'" data-select-slot="'+i+'" aria-pressed="'+(i===state.selected)+'"><span class="slot-index">'+String(i+1).padStart(2,'0')+'</span>'+itemIcon(id)+'<span><span class="item-name">'+(data?.name||'Empty slot')+'</span><span class="item-sub" style="display:block">'+(data?.sub||(i<2?'Weapon slot':'Carried item slot'))+'</span></span><span class="item-count">'+countText(id)+'</span></button>';}).join('')+'</div><aside class="frame item-detail">'+(d?'<h2>'+d.name+'</h2><h3>'+d.sub+'</h3><p class="muted">'+d.description+'</p><div class="weapon-preview">'+itemIcon(id,true)+'</div><div class="detail-stat"><div><span class="eyebrow">'+(d.type==='weapon'?'Magazine':'Carried')+'</span><strong>'+d.count+'</strong></div><div><span class="eyebrow">'+(d.type==='weapon'?'Reserve':'Stack limit')+'</span><strong>'+d.reserve+'</strong></div></div>':'<h2>Empty slot</h2><p class="muted">Choose another slot or restore the sample loadout.</p><button class="action" data-action="restore-loadout">Restore sample loadout</button>')+'</aside></div><div><p class="eyebrow" style="margin-bottom:8px">AMMO RESERVES</p><div class="frame ammo-reserves">'+[['Light',0],['Medium',150],['Heavy',12],['Shells',16]].map(([name,n])=>'<div>'+icon(name==='Shells'?'shells':'ammo')+'<span class="eyebrow">'+name+'</span><strong>'+n+'</strong></div>').join('')+'</div></div><div class="inventory-actions"><button data-action="inventory-equip"><span class="key">E</span> EQUIP</button><button data-action="inventory-move"><span class="key">R</span> MOVE</button><button data-action="inventory-drop"><span class="key">X</span> DROP</button><button data-nav="hud"><span class="key">Esc</span> CLOSE</button></div></section>';}

const lessons=[
 ['Move','Use your movement controls to explore Ringfall. There is no fall damage.','keyboard'],
 ['Aim & fire','Aim down sights for precision. Keep moving between engagements.','target'],
 ['Reload','Reload before the next fight. Ammunition reserves sit outside the five carried slots.','ammo'],
 ['Inventory','Carry two weapons and three utility or consumable stacks. Choose your loadout deliberately.','gameplay'],
 ['Healing','Health and shields use different healing items. Their icons and colors remain distinct.','health'],
 ['Grapple','Hook onto solid surfaces. Release to keep your momentum.','grapple'],
 ['Vehicles','Use ground vehicles or an unarmed rotorcraft to rotate across the map.','controller'],
 ['Storm','Stay inside the safe zone. Watch the map and the next-zone timer.','storm']
];
function mainScreen(){return '<section class="screen menu-screen"><div class="menu-column"><img class="logo hero-logo" src="assets/logos/orbit-royale-primary.svg" alt="Orbit Royale"><div class="menu-actions">'+menuAction('Play','lobby',1,true)+menuAction('Training','training',2)+menuAction('Settings','mouse',3)+menuAction('Credits','credits',4)+'</div>'+footer()+'<p class="tagline">One world. One survivor.</p></div></section>';}
function lobbyScreen(){return '<section class="screen"><div class="screen-head"><img class="logo" src="assets/logos/orbit-royale-primary.svg" alt="Orbit Royale"><nav class="topnav"><button class="active" data-nav="lobby">Play</button><button data-nav="training">Training</button><button data-nav="mouse">Settings</button></nav></div><div class="lobby-main"><div class="frame"><p class="eyebrow">GAME MODE</p><h1 class="lobby-mode">Solo</h1></div><div class="frame"><p class="eyebrow">MISSION</p><h2 style="margin:8px 0 12px;text-transform:none">Ready for Ringfall</h2><p class="muted">Drop in, explore, and be the last one standing.</p><div class="lobby-map" style="margin-top:20px"><div>'+mapArt(true)+'</div><div class="lobby-facts"><div><p class="eyebrow">MAP</p><h3>Ringfall</h3></div><div><p class="eyebrow">POPULATION</p><p>1 player + 59 bots</p></div><div><p class="eyebrow">COMBATANTS</p><h2>60 <span style="font-size:16px;text-transform:none">combatants</span></h2></div></div></div></div><button class="action primary big-primary" data-nav="match-loading">Start match <span>→</span></button><div class="frame callsign"><div><p class="eyebrow">CALLSIGN</p><strong>'+esc(state.callsign)+'</strong></div><button class="action" data-action="callsign">Edit callsign</button><button class="action" data-nav="learn">Learn controls</button></div></div></section>';}
function loadingScreen(asset){return '<section class="screen">'+head('lobby')+'<div class="loading-layout"><div class="loading-info"><p class="eyebrow">'+(asset?'DOWNLOADING ASSETS':'SOLO · 60 COMBATANTS')+'</p><h1>'+(asset?'Preparing Orbit Royale':'Ringfall awaits')+'</h1><div class="frame"><h3 class="lime">'+(asset?'Downloading assets':'Preparing match')+'</h3><div class="progress" style="margin-top:24px"><div class="progress-track"><div class="progress-fill" style="width:'+(asset?state.download:45)+'%"></div></div>'+(asset?'<strong class="progress-percent">'+state.download+'%</strong>':'')+'</div>'+(asset?'<p class="muted" style="margin-top:12px">Ringfall terrain</p>':'')+'</div><div class="checklist">'+(asset?['Characters','Equipment','Terrain','Audio']:['Terrain ready','Equipment ready','Preparing bots','Ready']).map((s,i)=>'<div class="frame"><span>'+String(i+1).padStart(2,'0')+' &nbsp; '+s.toUpperCase()+'</span><span class="'+(i<3?'checkmark':'muted')+'">'+(i<2?'✓':i===2?'◉':'○')+'</span></div>').join('')+'</div><div class="tip">'+icon('gameplay')+(asset?'Carry a grapple to cross gaps and reach high ground.':'No fall damage. Use your grapple to keep moving.')+'</div><div style="display:flex;gap:16px">'+(asset?'<button class="action primary" data-action="advance-download">Advance demo progress</button><button class="action" data-nav="lobby">Cancel</button>':'<button class="action primary" data-nav="hud">Enter HUD demo →</button><button class="action" data-nav="learn">Learn controls</button>')+'</div></div>'+(asset?'<div></div>':'<div class="frame loading-ship">'+shipArt()+'</div>')+'</div></section>';}
function matchMenu(){return '<section class="screen menu-screen"><div class="menu-column"><img class="logo hero-logo" src="assets/logos/orbit-royale-primary.svg" alt="Orbit Royale"><p class="eyebrow">SOLO · RINGFALL</p><p class="muted">Match continues</p><div class="menu-actions" style="margin-top:24px">'+menuAction('Resume','hud',0,true)+menuAction('Settings','mouse')+menuAction('Learn controls','learn')+menuAction('Report a problem','report')+'<hr style="width:100%;border:0;border-top:1px solid var(--rule)">'+menuAction('<span class="coral">Leave match</span>','leave',0,false,'action')+'</div>'+footer()+'</div></section>';}
function learnScreen(){const l=lessons[state.lesson];return '<section class="screen">'+head(returnTo)+'<div class="guide-layout"><div class="lessons">'+lessons.map(([title],i)=>'<button class="action lesson '+(i===state.lesson?'selected':'')+'" data-lesson="'+i+'"><span class="numeric">'+String(i+1).padStart(2,'0')+'</span>'+title+'<span style="margin-left:auto">→</span></button>').join('')+'</div><div class="frame guide-content"><p class="eyebrow">'+(state.lesson+1)+' / 8</p><h1>'+l[0]+'</h1><p>'+l[1]+'</p><div class="guide-illustration">'+(l[2]==='grapple'?svg('<path d="M450 40v230m0-190h120m-120 80h120M25 220l100-30 80 35-30 60H40Z"/><circle cx="205" cy="146" r="22"/><path d="M196 170 142 207l-30 55m30-55 45 58m14-94 46-33 44-15m-47 16 16 38" stroke-width="8"/><path d="M290 123 450 73" stroke="#c5f277" stroke-width="3"/><circle cx="450" cy="73" r="9" stroke="#c5f277"/>','0 0 600 300','map-art'):icon(l[2]))+'</div></div></div><div class="guide-footer"><button class="action" data-action="lesson-prev" '+(state.lesson===0?'disabled':'')+'>← Previous</button><button class="action primary" data-action="lesson-next">'+(state.lesson===7?'Finish':'Next →')+'</button><button class="action" data-nav="lobby">Skip guide</button><button class="action" data-nav="hud">Practice</button></div></section>';}
function mapScreen(){return '<section class="screen"><div class="screen-head"><h1>Ringfall</h1><p class="eyebrow">SOLO · 23 LEFT</p><div class="line"></div><button class="action" data-nav="hud">Close ×</button></div><div class="map-layout"><div class="frame map-board" id="map-board" aria-label="Ringfall map. Click to place marker; drag to pan." tabindex="0">'+mapArt()+'</div><div class="map-side"><div class="frame"><h2>Legend</h2>'+[['circle','Safe zone','Play area',''],['storm','Ion storm','Outside the safe zone','color:#b98aff'],['arrow','You','Your current position',''],['marker','Marker','Placed by you','color:var(--lime)']].map(([i,n,d,c])=>'<div class="legend-row"><div style="'+c+'">'+icon(i)+'</div><div><strong>'+n+'</strong><p class="muted">'+d+'</p></div></div>').join('')+'</div><div class="frame"><p class="eyebrow">NEXT ZONE</p><div class="map-timer lime">◷ <span style="color:var(--text)">01:42</span></div></div></div></div><div class="footer"><button class="hint" data-action="place-marker">Place marker</button><button class="hint" data-action="remove-marker">Remove marker</button><button class="hint" data-action="zoom-in">+ Zoom</button><button class="hint" data-action="zoom-out">− Zoom</button><button class="hint" data-action="reset-map">Reset view</button><span class="muted">Drag to pan · Arrow keys to pan</span></div></section>';}
function reportScreen(){return '<section class="screen">'+head(returnTo)+'<h1>Report a problem</h1><p class="eyebrow">HELP US IMPROVE ORBIT ROYALE</p><div class="report-layout"><div><h3>1. What type of issue?</h3><div class="issue-types">'+[['Bug','bug'],['Visual','eye'],['Audio','audio'],['Controls','controller'],['Performance','video'],['Other','report']].map(([n,i])=>'<button class="action '+(state.reportType===n?'selected':'')+'" data-issue="'+n+'" aria-pressed="'+(state.reportType===n)+'">'+icon(i)+n+'</button>').join('')+'</div><h3><label for="report-description">2. What happened?</label></h3><textarea id="report-description" class="report-description" maxlength="1000" placeholder="Describe the issue…">'+esc(state.reportText)+'</textarea><p class="report-count"><span id="report-count">'+state.reportText.length+'</span> / 1000</p></div><aside class="report-side"><h3>3. Add an attachment (optional)</h3><div class="frame"><div class="attachment-preview">'+mapArt(true)+'</div><label class="checkbox"><input type="checkbox" id="include-reference">Include displayed map reference</label><p class="muted" style="margin-top:14px">This preview is a map illustration, not an automatic screenshot capture.</p></div><div class="frame"><ul><li>This is a local feedback form.</li><li>No position, logs or private data are included.</li><li>The report downloads as a JSON file.</li></ul></div></aside></div><div style="display:flex;gap:20px"><button class="action primary" data-action="save-report">Save report →</button><button class="action" data-nav="'+returnTo+'">Cancel</button></div></section>';}
function resultScreen(victory){return '<section class="screen"><p class="eyebrow">SOLO · RINGFALL</p><div class="results-layout"><div class="results-copy"><p class="eyebrow '+(victory?'lime':'coral')+'">'+(victory?'VICTORY':'ELIMINATED')+'</p><h1>'+(victory?'Last survivor':'Deployment ended')+'</h1><div class="placement">'+(victory?'#1':'#12')+' <small>/ 60</small></div><div class="frame stats">'+(victory?[[8,'Eliminations'],['1,240','Damage'],['16:42','Survival']]:[[3,'Eliminations'],[620,'Damage'],['11:08','Survival']]).map(([v,n])=>'<div><strong>'+v+'</strong><span class="eyebrow">'+n+'</span></div>').join('')+'</div><p class="eyebrow">'+(victory?'MATCH COMPLETE':'REVIEW YOUR LOADOUT AND TRY ANOTHER ROUTE')+'</p>'+menuAction('Play again','match-loading',0,true)+menuAction('Return to lobby','lobby')+'</div><div class="result-art">'+(victory?svg('<path d="M88 12 196 18l31 54-5 70-32 22-70-15-37-58ZM106 60h96v50h-80Z M127 149 77 197l-8 109 46 30-16 117h120l-18-127 49-24-15-117-42-30 M112 188h91v105h-91Z M113 338l42-20 57 20m-45-125 82 44-31 30-78-49M92 216l46 38 53-10" />','0 0 300 470','map-art'):mapArt(true))+'</div></div></section>';}
function trainingScreen(){return '<section class="screen">'+head('main')+'<h1>Training</h1><p class="muted">Explore the interface and learn the controls.</p><div class="menu-column" style="margin-top:30px">'+menuAction('Learn controls','learn',1,true)+menuAction('HUD preview','hud',2)+menuAction('Inventory practice','inventory',3)+menuAction('Ringfall map','map',4)+'</div></section>';}
function creditsScreen(){return '<section class="screen">'+head('main')+'<h1>Credits</h1><div class="credits"><h2>Orbit Royale</h2><p>Game concept and direction: EOSHunter.</p><p>UI concepts, vector identity and this screen prototype: Codex.</p><p>Typography: Oxanium, Barlow and IBM Plex Mono. Font authorship and licenses are included with the bundled font files.</p><p>This is a menu and UI prototype. Match figures and loading progress are sample state; combat and 3D rendering are not implemented here.</p></div></section>';}
function render(){
 applyAccessibility();
 let html='';
 if(pages.some(p=>p.id===current))html=settingsScreen(current);
 else if(current==='main')html=mainScreen();
 else if(current==='lobby')html=lobbyScreen();
 else if(current==='asset-loading'||current==='match-loading')html=loadingScreen(current==='asset-loading');
 else if(current==='match-menu')html=matchMenu();
 else if(current==='inventory')html=inventoryScreen();
 else if(current==='hud'||current==='leave-confirmation')html=hudScreen();
 else if(current==='map')html=mapScreen();
 else if(current==='learn')html=learnScreen();
 else if(current==='report')html=reportScreen();
 else if(current==='victory'||current==='eliminated')html=resultScreen(current==='victory');
 else if(current==='training')html=trainingScreen();
 else if(current==='credits')html=creditsScreen();
 else if(current==='reset-confirmation')html=settingsScreen('mouse');
 app.innerHTML=html;
 document.documentElement.style.setProperty('--text-scale',state.settings.textScale/100);
 $('#current-name').textContent=screens.find(s=>s.id===current)?.name||'Main menu';
 updateReference();bindMap();drawFrames();
 if(current==='reset-confirmation')resetDialog(true);
 if(current==='leave-confirmation')leaveDialog(true);
}
function updateReference(){const s=screens.find(x=>x.id===current);const img=$('#reference-image');if(s?.ref){img.src='references/'+s.ref;img.hidden=false;img.alt=s.name+' concept';$('#reference-name').textContent=s.name;}else{img.removeAttribute('src');img.hidden=true;$('#reference-name').textContent='Supplementary screen — no separate concept image.';}}
function showDropdown(trigger,options,selected,onSelect){
 if(dropdown.matches(':popover-open'))dropdown.hidePopover();
 dropdown.innerHTML=options.map((o,i)=>o.heading?'<div class="dropdown-heading">'+esc(o.heading)+'</div>':'<button role="option" aria-selected="'+(o.value===selected)+'" data-option="'+i+'">'+esc(o.label??o.value)+'</button>').join('');
 dropdown.setAttribute('aria-label',trigger.getAttribute('aria-label')||'Choose screen');
 const r=trigger.getBoundingClientRect();dropdown.style.left=Math.max(8,Math.min(r.left,innerWidth-360))+'px';dropdown.style.top=(r.bottom+6)+'px';dropdown.style.minWidth=Math.min(Math.max(r.width,200),innerWidth-16)+'px';dropdown.style.maxWidth=(innerWidth-16)+'px';
 dropdown.showPopover();trigger.setAttribute('aria-expanded','true');
 if(dropdown.getBoundingClientRect().bottom>innerHeight){dropdown.style.top=Math.max(8,r.top-dropdown.offsetHeight-6)+'px';}
 const chosen=dropdown.querySelector('[aria-selected=true]')||dropdown.querySelector('button');chosen?.focus();
 dropdown.onclick=e=>{const b=e.target.closest('[data-option]');if(!b)return;dropdown.hidePopover();trigger.setAttribute('aria-expanded','false');trigger.focus();onSelect(options[Number(b.dataset.option)].value);};
 dropdown.onkeydown=e=>{const bs=[...dropdown.querySelectorAll('button')],index=bs.indexOf(document.activeElement);if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();const n=e.key==='Home'?0:e.key==='End'?bs.length-1:(index+(e.key==='ArrowDown'?1:-1)+bs.length)%bs.length;bs[n].focus();}else if(e.key==='Escape'){e.preventDefault();dropdown.hidePopover();trigger.setAttribute('aria-expanded','false');trigger.focus();}};
 dropdown.ontoggle=e=>{if(e.newState==='closed')trigger.setAttribute('aria-expanded','false');};
}
function openModal(html){if(!/id="modal-title">(?:Reset|Leave)/.test(html))modal.className='';modalOrigin=document.activeElement;modal.innerHTML=html;modal.showModal();}
function closeModal(){modal.close();}
modal.addEventListener('close',()=>{capture=null;clearInterval(gamepadTimer);if(modalOrigin?.isConnected)modalOrigin.focus();});
function resetDialog(direct=false){const p=pages.find(p=>p.id===(current==='reset-confirmation'?'mouse':current))||pages.find(p=>p.id===lastSettings);const cat=p.category;openModal('<h2 id="modal-title">Reset '+categories[cat]+'?</h2><p>Restore this category to its default settings.</p><div class="modal-actions"><button class="action" autofocus data-modal="cancel'+(direct?'-reset':'')+'">× Cancel</button><button class="action danger" data-reset-category="'+cat+'" data-direct="'+direct+'">↶ Reset</button></div>');}
function leaveDialog(direct=false){openModal('<div style="width:80px;height:80px;margin:0 auto 24px">'+icon('exit')+'</div><h2 id="modal-title" style="text-align:center">Leave this match?</h2><p style="text-align:center">You will return to the lobby and leave the current match.</p><div class="modal-actions"><button class="action" autofocus data-modal="'+(direct?'stay-direct':'cancel')+'">Stay</button><button class="action danger" data-nav="lobby">Leave match</button></div>');}
function setSetting(id,value){
 state.settings[id]=value;
 if(['shadows','textures','foliage','effects','antialiasing'].includes(id))state.settings.quality='Custom';
 if(id==='quality'&&value!=='Custom'){['shadows','textures','foliage','effects'].forEach(k=>state.settings[k]=value);state.settings.antialiasing=value==='Low'?'Disabled':'Enabled';}
 persist();
}
function rowById(id){return pages.flatMap(p=>p.binding?[]:p.rows).find(r=>r.id===id);}
function refreshControl(id){const r=rowById(id);const element=$('[data-range="'+id+'"]');if(element){element.value=state.settings[id];element.style.setProperty('--fill',((state.settings[id]-r.min)/(r.max-r.min)*100)+'%');element.closest(".control").querySelector("output").textContent=fmt(r);}}
function resetCategory(cat){pages.filter(p=>p.category===cat).forEach(p=>{if(p.binding)p.rows.forEach((_,i)=>delete state.bindings[p.id+':'+i]);else p.rows.forEach(r=>state.settings[r.id]=r.value)});persist();closeModal();if(current==='reset-confirmation')nav('mouse');else render();notify('Category restored to defaults');}
function moveItem(target){const from=state.selected;if((from<2)!==(target<2)){notify('Weapons stay in slots 1–2; carried items stay in slots 3–5.');return;}[state.items[from],state.items[target]]=[state.items[target],state.items[from]];if(state.equipped===from)state.equipped=target;else if(state.equipped===target)state.equipped=from;state.selected=target;closeModal();render();}
function bindingValue(k,column){const split=k.split(':'),p=pages.find(p=>p.id===split[0]),i=Number(split[1]);return (state.bindings[k]||[p.rows[i][1],'—'])[column];}
function startRebind(k,column){const [pid,idx]=k.split(':'),p=pages.find(x=>x.id===pid);capture={k,column,pid,idx:Number(idx),candidate:null};openModal('<h2 id="modal-title">Rebind '+p.rows[idx][0]+'</h2><p>'+(p.controller?'Press a controller button, or choose a sample button below.':'Press a keyboard key or mouse button. Escape cancels.')+'</p><div class="capture" id="capture-state">Waiting for input…</div>'+(p.controller?'<div class="segments" style="flex-wrap:wrap">'+['A','B','X','Y','LT','RT','LB','RB','View','Menu','D-pad Up'].map(v=>'<button data-capture-value="'+v+'">'+v+'</button>').join('')+'</div>':'')+'<div class="modal-actions"><button class="action" data-modal="cancel" autofocus>Cancel</button><button class="action" data-modal="clear-binding">Clear</button></div>');if(p.controller){let prior=[];gamepadTimer=setInterval(()=>{const pad=[...(navigator.getGamepads?.()||[])].find(Boolean);if(!pad)return;const names=['A','B','X','Y','LB','RB','LT','RT','View','Menu','LS','RS','D-pad Up','D-pad Down','D-pad Left','D-pad Right'];pad.buttons.forEach((b,i)=>{if(b.pressed&&!prior[i])acceptBinding(names[i]||'Button '+i)});prior=pad.buttons.map(b=>b.pressed);},80);}}
function acceptBinding(value){if(!capture)return;const p=pages.find(p=>p.id===capture.pid);let conflict=null;for(let i=0;i<p.rows.length;i++){const k=p.id+':'+i;for(let col=0;col<(p.controller?1:2);col++){if(k===capture.k&&col===capture.column)continue;if(bindingValue(k,col)===value)conflict={k,column:col,label:p.rows[i][0]};}}
 if(conflict){capture.candidate=value;capture.conflict=conflict;$('#capture-state').innerHTML=esc(value)+' is already assigned to '+esc(conflict.label)+'.<br><button class="action primary" style="margin-top:16px" data-modal="resolve-binding">Move binding here</button>';return;}
 saveBinding(value);}
function saveBinding(value){if(!capture)return;const c=capture;if(c.conflict&&value===c.candidate){const k=c.conflict.k;state.bindings[k]=[bindingValue(k,0),bindingValue(k,1)];state.bindings[k][c.conflict.column]='—';}
 state.bindings[c.k]=[bindingValue(c.k,0),bindingValue(c.k,1)];state.bindings[c.k][c.column]=value;persist();closeModal();render();notify('Binding saved');}
function onAction(action){
 if(action==='reset')resetDialog();
 else if(action==='leave')leaveDialog();
 else if(action==='callsign')openModal('<h2 id="modal-title">Edit callsign</h2><p>Choose a callsign for this local prototype.</p><input id="callsign-field" maxlength="24" aria-label="Callsign" value="'+esc(state.callsign)+'" autofocus><div class="modal-actions"><button class="action" data-modal="cancel">Cancel</button><button class="action primary" data-modal="save-callsign">Save</button></div>');
 else if(action==='advance-download'){state.download=Math.min(100,state.download+16);if(state.download===100){notify('Demo asset stage complete');nav('lobby')}else render();}
 else if(action==='lesson-prev'){state.lesson=Math.max(0,state.lesson-1);render();}
 else if(action==='lesson-next'){if(state.lesson===7)nav('lobby');else{state.lesson++;render();}}
 else if(action==='inventory-equip'){if(!state.items[state.selected]){notify('This slot is empty');return;}state.equipped=state.selected;notify('Equipped '+itemInfo[state.items[state.selected]].name);nav('hud');}
 else if(action==='inventory-drop'){if(!state.items[state.selected]){notify('This slot is empty');return;}state.items[state.selected]=null;render();notify('Item dropped from the demo loadout');}
 else if(action==='inventory-move'){if(!state.items[state.selected]){notify('Select an occupied slot first');return;}openModal('<h2 id="modal-title">Move item</h2><p>Choose a compatible slot. Occupied slots swap items.</p><div class="segments" style="margin-top:24px;flex-wrap:wrap">'+state.items.map((_,i)=>'<button data-move-target="'+i+'" '+((i<2)!==(state.selected<2)||i===state.selected?'disabled':'')+'>Slot '+(i+1)+'</button>').join('')+'</div><div class="modal-actions"><button class="action" data-modal="cancel" autofocus>Cancel</button></div>');}
 else if(action==='restore-loadout'){state.items=['rifle','shotgun','grapple','pack','patch'];state.selected=state.equipped=0;render();}
 else if(action==='save-report'){const report={game:'Orbit Royale',prototype:'UI v0.1',type:state.reportType,description:state.reportText,referenceIncluded:$('#include-reference')?.checked||false};if(report.referenceIncluded)report.reference='Ringfall map illustration; not a gameplay capture';const a=document.createElement('a');const url=URL.createObjectURL(new Blob([JSON.stringify(report,null,2)],{type:'application/json'}));a.href=url;a.download='orbit-royale-feedback.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Local report downloaded');}
 else if(action==='remove-marker'){state.marker=null;refreshMap();}
 else if(action==='place-marker'){state.marker={x:470,y:350};refreshMap();}
 else if(action==='zoom-in'){state.mapZoom=Math.min(2.5,state.mapZoom+.2);refreshMap();}
 else if(action==='zoom-out'){state.mapZoom=Math.max(.7,state.mapZoom-.2);refreshMap();}
 else if(action==='reset-map'){state.mapZoom=1;state.mapPan={x:0,y:0};refreshMap();}
}
function clickHandler(e){
 const button=e.target.closest('button');if(!button||button.disabled)return;
 if(button.dataset.nav){const target=button.dataset.nav;if(target==='mouse'){returnTo=['hud','match-menu','inventory','map'].includes(current)?'match-menu':'main';helpIndex=0;}if(['learn','report'].includes(target))returnTo=current==='match-menu'?'match-menu':'lobby';nav(target);return;}
 if(button.dataset.action){onAction(button.dataset.action);return;}
 if(button.dataset.choice){const r=rowById(button.dataset.choice);showDropdown(button,r.options.map(v=>({value:v})),state.settings[r.id],v=>{setSetting(r.id,v);render();$('[data-choice="'+r.id+'"]')?.focus();});return;}
 if(button.dataset.adjust){const r=rowById(button.dataset.adjust),dir=Number(button.dataset.direction);if(r.type==='range'){setSetting(r.id,Math.max(r.min,Math.min(r.max,state.settings[r.id]+dir*r.step)));refreshControl(r.id);}else if(r.type==='toggle'){setSetting(r.id,!state.settings[r.id]);render();}else{const i=r.options.indexOf(state.settings[r.id]);setSetting(r.id,r.options[(i+dir+r.options.length)%r.options.length]);render();}return;}
 if(button.dataset.toggle){const id=button.dataset.toggle;if(id==='fullscreen'){toggleFullscreen();return;}setSetting(id,!state.settings[id]);render();$('[data-toggle="'+id+'"]')?.focus();return;}
 if(button.dataset.segment){setSetting(button.dataset.segment,button.dataset.value);render();$('[data-segment="'+button.dataset.segment+'"][data-value="'+button.dataset.value+'"]')?.focus();return;}
 if(button.dataset.bind){startRebind(button.dataset.bind,Number(button.dataset.column));return;}
 if(button.dataset.selectSlot!==undefined){state.selected=Number(button.dataset.selectSlot);render();$('[data-select-slot="'+state.selected+'"]')?.focus();return;}
 if(button.dataset.equip!==undefined){state.equipped=Number(button.dataset.equip);render();return;}
 if(button.dataset.lesson){state.lesson=Number(button.dataset.lesson);render();return;}
 if(button.dataset.issue){state.reportType=button.dataset.issue;render();return;}
 if(button.dataset.resetCategory){resetCategory(Number(button.dataset.resetCategory));return;}
 if(button.dataset.moveTarget!==undefined){moveItem(Number(button.dataset.moveTarget));return;}
 if(button.dataset.captureValue){acceptBinding(button.dataset.captureValue);return;}
 if(button.dataset.modal){const a=button.dataset.modal;if(a==='clear-binding'){saveBinding('—');}else if(a==='resolve-binding'){saveBinding(capture.candidate);}else if(a==='save-callsign'){const value=$('#callsign-field').value.trim();if(!value){notify('Enter a callsign');return;}state.callsign=value;persist();closeModal();render();}else if(a==='cancel-reset'){closeModal();nav('mouse');}else if(a==='stay-direct'){closeModal();nav('hud');}else closeModal();}
}
app.addEventListener('click',clickHandler);modal.addEventListener('click',clickHandler);
app.addEventListener('input',e=>{if(e.target.dataset.range){const id=e.target.dataset.range;setSetting(id,Number(e.target.value));refreshControl(id);}if(e.target.id==='report-description'){state.reportText=e.target.value;$('#report-count').textContent=state.reportText.length;}});
function focusHelp(e){const row=e.target.closest('[data-help]');if(!row)return;const p=pages.find(x=>x.id===current);if(!p||helpIndex===Number(row.dataset.help))return;helpIndex=Number(row.dataset.help);document.querySelectorAll('.setting-row').forEach(r=>r.classList.toggle('active',r===row));$('#help-panel').innerHTML=helpContent(p,helpIndex);}
app.addEventListener('focusin',focusHelp);app.addEventListener('mouseover',focusHelp);
function keyName(e){return e.key===' '?'Space':({Control:'Ctrl',ArrowUp:'Up',ArrowDown:'Down',ArrowLeft:'Left',ArrowRight:'Right'}[e.key]|| (e.key.length===1?e.key.toUpperCase():e.key));}
document.addEventListener('keydown',e=>{
 if(capture&&e.key!=='Escape'&&!pages.find(p=>p.id===capture.pid)?.controller){e.preventDefault();acceptBinding(keyName(e));return;}
 if(e.key==='Escape'){if(modal.open||dropdown.matches(':popover-open'))return;if(current==='inventory'||current==='map')nav('hud');else if(current==='hud')nav('match-menu');else if(pages.some(p=>p.id===current))nav(returnTo);else if(current==='match-menu')nav('hud');else if(current!=='main')nav('main');return;}
 if(modal.open||dropdown.matches(':popover-open')||e.target.matches('input,textarea,[contenteditable]'))return;
 if(current==='hud'){
  if(/^[1-5]$/.test(e.key)){state.equipped=Number(e.key)-1;render();return;}
  const inventoryBinding=bindingValue('keyboard-bindings:8',0),mapBinding=bindingValue('keyboard-bindings:9',0);
  if(keyName(e)===inventoryBinding){e.preventDefault();nav('inventory');return;}
  if(keyName(e)===mapBinding){e.preventDefault();nav('map');return;}
 }
 if(current==='inventory'){if(e.key==='Tab'){e.preventDefault();nav('hud');}else if(e.key.toLowerCase()==='e')onAction('inventory-equip');else if(e.key.toLowerCase()==='r')onAction('inventory-move');else if(e.key.toLowerCase()==='x')onAction('inventory-drop');else if(/^[1-5]$/.test(e.key)){state.selected=Number(e.key)-1;render();}}
 const tab=e.target.closest('[role=tab]');if(tab&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const ts=[...document.querySelectorAll('[role=tab]')],i=ts.indexOf(tab),j=e.key==='Home'?0:e.key==='End'?ts.length-1:(i+(e.key==='ArrowRight'?1:-1)+ts.length)%ts.length;nav(ts[j].dataset.nav);document.querySelector('[role=tab][aria-selected=true]')?.focus();}
 if(current==='map'&&e.target.id==='map-board'&&e.key.startsWith('Arrow')){e.preventDefault();if(e.key==='ArrowLeft')state.mapPan.x-=20;if(e.key==='ArrowRight')state.mapPan.x+=20;if(e.key==='ArrowUp')state.mapPan.y-=20;if(e.key==='ArrowDown')state.mapPan.y+=20;refreshMap();}
});
modal.addEventListener('pointerdown',e=>{if(capture&&!pages.find(p=>p.id===capture.pid)?.controller&&e.target.id==='capture-state'){e.preventDefault();acceptBinding('Mouse'+(e.button+1));}});
modal.addEventListener('cancel',()=>{if(current==='reset-confirmation')setTimeout(()=>nav('mouse'),0);if(current==='leave-confirmation')setTimeout(()=>nav('hud'),0);});
function refreshMap(){const board=$('#map-board');if(board){board.innerHTML=mapArt();drawFrames();}}
function bindMap(){const board=$('#map-board');if(!board)return;let start=null,moved=false;
 board.addEventListener('pointerdown',e=>{start={x:e.clientX,y:e.clientY,pan:{...state.mapPan}};moved=false;board.setPointerCapture(e.pointerId);});
 board.addEventListener('pointermove',e=>{if(!start)return;const dx=e.clientX-start.x,dy=e.clientY-start.y;if(Math.abs(dx)+Math.abs(dy)>5)moved=true;if(moved){const scale=940/board.clientWidth;state.mapPan={x:start.pan.x+dx*scale,y:start.pan.y+dy*scale};refreshMap();}});
 board.addEventListener('pointerup',e=>{if(!start)return;if(!moved){const s=board.querySelector('svg'),point=new DOMPoint(e.clientX,e.clientY).matrixTransform(s.getScreenCTM().inverse());state.marker={x:(point.x-state.mapPan.x)/state.mapZoom,y:(point.y-state.mapPan.y)/state.mapZoom};refreshMap();}start=null;});
 board.addEventListener('pointercancel',()=>start=null);
 board.addEventListener('wheel',e=>{e.preventDefault();state.mapZoom=Math.max(.7,Math.min(2.5,state.mapZoom+(e.deltaY<0?.1:-.1)));refreshMap();},{passive:false});
}
function screenPicker(){const options=[];let lastGroup='';screens.forEach(s=>{const group=pages.includes(s)?'Settings':'Menus / gameplay';if(group!==lastGroup){options.push({heading:group});lastGroup=group;}options.push({value:s.id,label:s.name});});showDropdown($('#screen-picker'),options,current,id=>{helpIndex=0;nav(id)});}
$('#screen-picker').addEventListener('click',screenPicker);
function cycleScreen(dir){const i=screens.findIndex(s=>s.id===current);helpIndex=0;nav(screens[(i+dir+screens.length)%screens.length].id);}
$('#previous-screen').addEventListener('click',()=>cycleScreen(-1));$('#next-screen').addEventListener('click',()=>cycleScreen(1));
$('#reference-toggle').addEventListener('click',()=>{$('#reference').hidden=!$('#reference').hidden;$('#reference-toggle').setAttribute('aria-pressed',String(!$('#reference').hidden));});
$('#reference-close').addEventListener('click',()=>{$('#reference').hidden=true;$('#reference-toggle').setAttribute('aria-pressed','false');});
async function toggleFullscreen(){try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();state.settings.fullscreen=!!document.fullscreenElement;persist();if(current==='video-display')render();}catch{notify('Fullscreen is unavailable in this browser view. Use the browser fullscreen control.');}}
$('#fullscreen').addEventListener('click',toggleFullscreen);
document.addEventListener('fullscreenchange',()=>{state.settings.fullscreen=!!document.fullscreenElement;persist();});
window.addEventListener('hashchange',()=>{const id=location.hash.slice(1);if(id!==current&&screens.some(s=>s.id===id)){current=id;helpIndex=0;if(modal.open)modal.close();render();}});
window.addEventListener('gamepadconnected',()=>{const s=$('.controller-status');if(s)s.textContent=controllerStatus();});
window.addEventListener('gamepaddisconnected',()=>{const s=$('.controller-status');if(s)s.textContent=controllerStatus();});
current=screens.some(s=>s.id===location.hash.slice(1))?location.hash.slice(1):'main';render();

function drawFrames(){
 document.querySelectorAll('.frame,.menu-action,.inventory-item,.quick-slot,.category').forEach(el=>{
  el.querySelector(':scope > .panel-outline')?.remove();
  const w=el.clientWidth,h=el.clientHeight;if(!w||!h)return;const c=el.classList.contains('quick-slot')?10:16;
  const selected=el.classList.contains('selected')||el.classList.contains('active');
  const d='M'+c+' 3H'+(w-c)+'L'+(w-3)+' '+c+'V'+(h-c)+'L'+(w-c)+' '+(h-3)+'H'+c+'L3 '+(h-c)+'V'+c+'Z';
  el.insertAdjacentHTML('beforeend','<svg class="panel-outline" viewBox="0 0 '+w+' '+h+'" preserveAspectRatio="none" aria-hidden="true"><path d="'+d+'" fill="none" stroke="'+(selected?'#c5f277':'#60718a')+'" stroke-width="'+(selected?2:1)+'"/></svg>');
 });
}
window.addEventListener('resize',()=>{if(dropdown.matches(':popover-open'))dropdown.hidePopover();drawFrames();});

document.addEventListener('keydown',e=>{
 if(modal.open||dropdown.matches(':popover-open')||capture||e.target.matches('input,textarea'))return;
 const actions=[...document.querySelectorAll('.menu-actions .menu-action,.mr-actions .mr-button')];
 if(actions.length&&['ArrowUp','ArrowDown'].includes(e.key)){
  e.preventDefault();const index=actions.indexOf(document.activeElement);const active=Math.max(0,index<0?actions.findIndex(b=>b.classList.contains('active')):index);
  const next=(active+(e.key==='ArrowDown'?1:-1)+actions.length)%actions.length;
  actions.forEach((b,i)=>b.classList.toggle(b.classList.contains('mr-button')?'is-selected':'active',i===next));drawFrames();actions[next].focus();
 }
});
